import {h,icon,button as btn,plural,highlightText,teachingText} from './ui.mjs';
import {senseFamilies,wordClasses,meaningCategories,classNames,findFamilies} from './wordlab.mjs';
import {isMarked} from './course.mjs';

const done=(state,id)=>state.completed[id]?.best;
const status=(state,id)=>done(state,id)===undefined?'Ещё не пройдено':`Лучший результат: ${done(state,id)}%`;
const sourceLinks=sources=>`<details class="lab-sources"><summary>Словарные источники</summary><div>${sources.map(s=>`<a href="${h(s.url)}" target="_blank" rel="noopener noreferrer">${h(s.label)} ${icon('arrow')}</a>`).join('')}</div></details>`;
function exampleTools(id,state){const saved=isMarked({id},state.bookmarks),difficult=isMarked({id},state.difficult);return `<div class="lab-example-tools"><button class="text-button" data-action="speak" data-id="${id}">${icon('sound')} Послушать</button><button class="icon-button ${saved?'marked':''}" data-action="bookmark" data-id="${id}" aria-pressed="${saved}" title="${saved?'Убрать из избранного':'Сохранить пример'}">${icon('bookmark')}</button><button class="remember-button ${difficult?'active':''}" data-action="difficult" data-id="${id}" aria-pressed="${difficult}">${icon('brain')}${difficult?'В сложных':'Не запомнил'}</button></div>`;}
function familyCard(f,state){return `<article class="panel family-card ${f.category}" data-card-action="lab-open-family" data-id="${f.id}"><div class="family-card-top"><span class="pill purple">${h(meaningCategories[f.category])}</span><small>${f.level}</small></div><h2 lang="da">${h(f.title)}</h2><p>${teachingText(f.summary)}</p><div class="family-preview">${[...new Set(f.senses.map(s=>s.form))].slice(0,4).map(form=>`<span lang="da">${h(form)}</span>`).join('')}</div><button class="family-card-bottom" data-action="lab-open-family" data-id="${f.id}" aria-label="Разобрать: ${h(f.title)}"><small>${f.senses.length} ${plural(f.senses.length,['значение','значения','значений'])} · ${done(state,f.id)===undefined?'к практике':done(state,f.id)+'%'}</small>${icon('arrow')}</button></article>`;}
function familyDetail(f,state){return `<button class="text-button lab-back" data-action="lab-back">${icon('chevron','back-icon')} Все слова</button><div class="lab-detail-heading"><div><span class="eyebrow">${h(meaningCategories[f.category])} · ${f.level}</span><h1 lang="da">${h(f.title)}</h1><p>${teachingText(f.summary)}</p></div><div>${btn(`${icon('target')} Проверить значения`,'begin-lesson','primary',`data-id="${f.id}"`)}<small>${status(state,f.id)}</small></div></div><div class="sense-grid">${f.senses.map((s,i)=>`<article class="panel sense-card"><div class="sense-card-heading"><span class="sense-number">${String(i+1).padStart(2,'0')}</span><button class="word-class-link" data-action="lab-open-class" data-id="${s.wordClass}">${h(classNames[s.wordClass])} ${icon('arrow')}</button></div><h2 lang="da">${h(s.form)}</h2><p class="sense-meaning">${h(s.ru)}</p><p class="sense-cue">${teachingText(s.note)}</p><div class="lab-example"><p lang="da">${h(s.da)}</p><span>${h(s.translation)}</span></div>${exampleTools(s.id,state)}</article>`).join('')}</div>${sourceLinks(f.sources)}`;}
function classCard(c,state){return `<article class="panel class-card" data-card-action="lab-open-class" data-id="${c.id}"><div class="class-card-top"><span class="class-letter">${h(c.title.slice(0,1))}</span><span class="pill blue">${c.level}</span></div><h2 lang="da">${h(c.title)}</h2><p class="class-russian">${h(c.ru)}</p><span class="class-alias" lang="da">${h(c.alias)}</span><p>${teachingText(c.summary)}</p><button class="family-card-bottom" data-action="lab-open-class" data-id="${c.id}" aria-label="Разобрать: ${h(c.title)}"><small>${h(c.cue)}</small>${icon(done(state,`wc-${c.id}`)>=80?'check':'arrow')}</button></article>`;}
function classDetail(c,state){return `<button class="text-button lab-back" data-action="lab-back">${icon('chevron','back-icon')} Все классы</button><div class="lab-detail-heading"><div><span class="eyebrow" lang="da">${h(c.alias)} · ${c.level}</span><h1 lang="da">${h(c.title)}</h1><p>${h(c.ru)} · ${h(c.cue)}</p></div><div>${btn(`${icon('target')} Узнать класс в предложении`,'begin-lesson','primary',`data-id="wc-${c.id}"`)}<small>${status(state,`wc-${c.id}`)}</small></div></div><div class="class-explanation"><div class="panel"><h2>Как узнать</h2><p>${teachingText(c.summary)}</p><p>${teachingText(c.forms)}</p></div><div class="class-contrast"><span>${icon('info')}</span><div><h2>Обрати внимание</h2><p>${teachingText(c.contrast)}</p></div></div></div><div class="section-title space-top"><h2>В предложении</h2></div><div class="sense-grid">${c.examples.map(e=>`<article class="panel sense-card"><span class="pill blue" lang="da">${h(classNames[c.id])}</span><div class="lab-example class-example"><p lang="da">${highlightText(e.da,e.target)}</p><span>${h(e.ru)}</span></div><p class="sense-cue">${teachingText(e.note)}</p>${exampleTools(e.id,state)}</article>`).join('')}</div>${sourceLinks(c.sources)}`;}

export function renderWordLab(c,modes){
 const tab=c.labTab||'meanings',state=c.state,selected=tab==='classes'?wordClasses.find(w=>w.id===c.labSelection):senseFamilies.find(f=>f.id===c.labSelection);
 const tabs=`<div class="lab-tabs" role="group" aria-label="Слова и грамматика"><button data-action="lab-tab" data-value="meanings" class="${tab==='meanings'?'active':''}" aria-pressed="${tab==='meanings'}">${icon('search')} Значения и сочетания</button><button data-action="lab-tab" data-value="classes" class="${tab==='classes'?'active':''}" aria-pressed="${tab==='classes'}">${icon('layers')} Классы слов · Ordklasser</button></div>`;
 const modeBar=`<div class="lab-mode-bar"><span>Режим практики</span>${modes}</div>`;
 if(selected)return `${tabs}${modeBar}${tab==='classes'?classDetail(selected,state):familyDetail(selected,state)}`;
 const families=findFamilies(c.labQuery,c.labCategory);
 return `<div class="page-heading"><div><h1>Форма знакомая. Смысл — по контексту.</h1><p>Артикль, предлог и место в предложении помогают понять слово.</p></div></div>${tabs}${tab==='classes'?`<div class="class-intro"><div><span class="eyebrow">ORDKLASSER</span><h2>Что делает слово в предложении?</h2><p>Начни с существительного и глагола, затем сравни остальные классы. У каждого есть примеры и короткая практика.</p></div><div class="class-mini-map"><span class="mint" lang="da">en bog</span><span class="purple" lang="da">læser</span><span class="peach" lang="da">god</span><span class="blue" lang="da">ikke</span></div></div>${modeBar}<div class="class-grid">${wordClasses.map(w=>classCard(w,state)).join('')}</div><p class="fine-print">Здесь 10 основных учебных групп. В разных описаниях языка границы и число классов могут отличаться: например, звукоподражания выделяют отдельно.</p>`:`<div class="meaning-intro"><div><span class="eyebrow">ОДНО СЛОВО · РАЗНЫЕ СИТУАЦИИ</span><h2 lang="da">en fyr / et fyr</h2><p>Парень, сосна, маяк или котёл? Сам артикль не всегда решает всё. Смотри на всю фразу.</p></div><button class="btn white" data-action="lab-open-family" data-id="meaning-fyr">Разобрать fyr ${icon('arrow')}</button></div><div class="lab-search-row"><label class="search-box">${icon('search')}<input id="lab-search" type="search" autocapitalize="none" autocorrect="off" spellcheck="false" autocomplete="off" enterkeyhint="search" value="${h(c.labQuery||'')}" aria-label="Поиск значений" placeholder="fyr, holder af, руководитель…"></label><span>${families.length} ${plural(families.length,['группа','группы','групп'])}</span></div><div class="filter-tabs lab-categories" role="group" aria-label="Тип слов и сочетаний">${[['all','Все'],...Object.entries(meaningCategories)].map(([id,label])=>`<button data-action="lab-category" data-value="${id}" class="${(c.labCategory||'all')===id?'active':''}" aria-pressed="${(c.labCategory||'all')===id}">${label}</button>`).join('')}</div>${modeBar}<div class="family-grid">${families.map(f=>familyCard(f,state)).join('')||'<div class="empty"><h2>Не нашлось подходящей группы.</h2><p>Попробуй датское слово, предлог или русский перевод.</p></div>'}</div>`}`;
}
